window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','z','x','c'].includes(k))e.preventDefault();keys.add(k);if(k==='enter'&&(state!=='play'&&state!=='pause'))begin();if(k==='escape'||k==='p'){if(state==='play')state='pause';else if(state==='pause')state='play';}if(k==='x'||k==='arrowup'||k===' '){if(!e.repeat)jump();}if(k==='c'&&!e.repeat)dash();});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
for(const b of document.querySelectorAll('[data-input]')){const a=b.dataset.input;const down=e=>{e.preventDefault();held[a]=true;b.classList.add('down');if(a==='jump')jump();if(a==='dash')dash();};const up=e=>{e.preventDefault();held[a]=false;b.classList.remove('down');};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up);}
canvas.addEventListener('pointerdown',e=>{if(state!=='play')begin();else shoot();});
function down(a){return held[a]||keys.has(a==='left'?'arrowleft':a==='right'?'arrowright':a==='shoot'?'z':'');}
function jump(){if(state!=='play')return;if(player.jumps<2){player.vy=-10.8;player.ground=false;player.jumps++;puff(player.x+20,player.y+58,5,'#f1dfbd');}}
function dash(){if(state!=='play'||player.dashCD>0)return;player.dash=12;player.dashCD=48;player.inv=Math.max(player.inv,14);player.vx=player.face*11;player.vy=0;}
function shoot(){if(state!=='play'||player.fire>0)return;player.fire=11;shots.push({x:player.x+player.w/2+player.face*23,y:player.y+29,vx:player.face*9,life:80});puff(player.x+player.w/2+player.face*24,player.y+29,3,'#f7dfa1');}
function puff(x,y,n,color){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*3,vy:(Math.random()-.8)*3,life:20+Math.random()*15,color,r:2+Math.random()*3});}
function rectHit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function hurt(){if(player.inv>0||state!=='play')return;player.hp--;player.inv=90;player.vy=-6;player.vx=-player.face*4;shake=9;puff(player.x+20,player.y+30,12,'#b4432b');if(player.hp<=0){state='lose';startBtn.textContent='TRY AGAIN';startBtn.hidden=false;pauseBtn.hidden=true;}}
function spawnBoss(){if(boss||player.x<LEVEL-650)return;boss={x:LEVEL-390,y:GROUND-210,w:150,h:210,hp:10,max:10,mode:'seed',timer:70,phase:0,flash:0};}
function update(dt){if(state!=='play')return;time+=dt;const s=dt/16.67;player.anim+=s;player.fire=Math.max(0,player.fire-s);player.dashCD=Math.max(0,player.dashCD-s);player.inv=Math.max(0,player.inv-s);player.dash=Math.max(0,player.dash-s);if(shake>0)shake*=.85;
const dir=(down('right')?1:0)-(down('left')?1:0);if(dir){player.face=dir;if(!player.dash)player.vx=dir*3.25;}else if(!player.dash)player.vx*=.78;
if(down('shoot'))shoot();if(player.dash<=0)player.vy+=.48*s;player.x+=player.vx*s;player.y+=player.vy*s;player.x=clamp(player.x,0,LEVEL-40);
if(player.y+player.h>=GROUND){player.y=GROUND-player.h;player.vy=0;if(!player.ground)player.jumps=0;player.ground=true;}else player.ground=false;
if(player.y>H+100)hurt();camera=clamp(player.x-330,0,LEVEL-W+160);
for(let i=shots.length-1;i>=0;i--){let b=shots[i];b.x+=b.vx*s;b.life-=s;if(b.life<=0||b.x<camera-30||b.x>camera+W+30)shots.splice(i,1);}
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(e.hp<=0){puff(e.x+20,e.y+20,12,'#9b3429');enemies.splice(i,1);score++;continue;}if(e.type==='mush'){e.x+=e.dir*.65*s;if(e.x<e.baseX-90||e.x>e.baseX+90)e.dir*=-1;if(e.baseX===undefined)e.baseX=e.x;}if(e.type==='bee'){e.phase+=.05*s;e.x+=e.dir*.8*s;e.y=e.base+Math.sin(e.phase)*25;if(e.x<e.baseX-75||e.x>e.baseX+75)e.dir*=-1;if(e.baseX===undefined)e.baseX=e.x;}if(e.type==='frog'){e.jump-=s;if(e.jump<=0){e.vy=-8;e.jump=85;}e.vy=(e.vy||0)+.38*s;e.y+=e.vy*s;if(e.y>GROUND-46){e.y=GROUND-46;e.vy=0;}e.x+=e.dir*.6*s;}
const box={x:e.x,y:e.y,w:e.type==='bee'?44:46,h:e.type==='bee'?32:48};for(let j=shots.length-1;j>=0;j--){if(rectHit({x:shots[j].x-5,y:shots[j].y-4,w:10,h:8},box)){e.hp--;shots.splice(j,1);e.flash=8;}}
if(rectHit({x:player.x+5,y:player.y+5,w:player.w-10,h:player.h-5},box)){if(player.dash>0){e.hp--;}else hurt();}}
if(player.x>LEVEL-330)spawnBoss();if(boss){const b=boss;b.timer-=s;b.flash=Math.max(0,b.flash-s);if(b.mode==='seed'&&b.timer<=0){for(let i=-1;i<=1;i++)enemyShots.push({x:b.x+40,y:b.y+75,vx:-3.5,vy:i*1.35, pink:i===0,life:160});b.mode='slam';b.timer=95;}else if(b.mode==='slam'&&b.timer<=0){b.mode='rise';b.timer=42;b.y=GROUND-210;shake=10;}else if(b.mode==='rise'&&b.timer<=0){b.mode='bees';b.timer=90;for(let i=0;i<2;i++)enemies.push({type:'bee',x:b.x-50-i*45,y:b.y+50,hp:2,dir:-1,base:b.y+50,baseX:b.x-50-i*45,phase:i});}else if(b.mode==='bees'&&b.timer<=0){b.mode='seed';b.timer=85;}
if(b.mode==='slam'){b.y+=8*s;if(b.y+b.h>=GROUND){b.y=GROUND-b.h;shake=12;}}
const bb={x:b.x+10,y:b.y+20,w:b.w-20,h:b.h-20};for(let j=shots.length-1;j>=0;j--){if(rectHit({x:shots[j].x-5,y:shots[j].y-5,w:10,h:10},bb)){b.hp--;b.flash=9;shots.splice(j,1);puff(b.x+35,b.y+80,3,'#f7da8d');}}
if(rectHit({x:player.x+4,y:player.y+5,w:player.w-8,h:player.h-6},bb)){if(player.dash>0)b.hp--;else hurt();}if(b.hp<=0){boss=null;state='win';startBtn.textContent='PLAY AGAIN';startBtn.hidden=false;pauseBtn.hidden=true;puff(LEVEL-330,220,70,'#e9c66e');}}
for(let i=enemyShots.length-1;i>=0;i--){const b=enemyShots[i];b.x+=b.vx*s;b.y+=b.vy*s;b.life-=s;if(b.pink&&player.dash>0&&Math.abs(b.x-(player.x+20))<34&&Math.abs(b.y-(player.y+30))<38){enemyShots.splice(i,1);player.hp=Math.min(3,player.hp+1);player.dashCD=0;parryFlash=22;puff(b.x,b.y,10,'#ed78ad');continue;}if(rectHit({x:b.x-9,y:b.y-9,w:18,h:18},{x:player.x,y:player.y,w:player.w,h:player.h})){enemyShots.splice(i,1);hurt();continue;}if(b.life<=0||b.x<camera-100)enemyShots.splice(i,1);}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*s;p.y+=p.vy*s;p.vy+=.1*s;p.life-=s;if(p.life<=0)particles.splice(i,1);}parryFlash=Math.max(0,parryFlash-s);
}

function draw(){ctx.save();let sx=shake?((Math.random()-.5)*shake):0;ctx.translate(sx,0);background();ctx.save();ctx.translate(-camera,0);terrain();for(const e of enemies)drawEnemy(e);if(boss)drawBoss(boss);for(const b of shots){ctx.fillStyle='#f8d783';ctx.beginPath();ctx.ellipse(b.x,b.y,8,5,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#4b2d17';ctx.lineWidth=2;ctx.stroke();}for(const b of enemyShots){ctx.fillStyle=b.pink?'#ef79a5':'#b8432d';ctx.beginPath();ctx.ellipse(b.x,b.y,10,7,Math.sin(time/120),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#482717';ctx.lineWidth=2;ctx.stroke();}drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/24,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.restore();hud();if(parryFlash>0){ctx.strokeStyle='#ee7ba8';ctx.lineWidth=8;ctx.globalAlpha=parryFlash/22;ctx.beginPath();ctx.arc(480,270,120,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}if(state==='title')titleScreen();if(state==='pause')overlay('PAUSED','Press P to resume');if(state==='lose')overlay('CURSES!','Your three chances are gone');if(state==='win')overlay('YOU DID IT!','THE WOODLAND IS FREE');film();ctx.restore();}
function background(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#d9bd87');g.addColorStop(.68,'#b58e5c');g.addColorStop(1,'#77543a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// sun
ctx.fillStyle='#f4d786';ctx.beginPath();ctx.arc(790-camera*.05,100,53,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#49321e';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#4b321f';ctx.beginPath();ctx.arc(774-camera*.05,93,4,0,7);ctx.arc(806-camera*.05,93,4,0,7);ctx.fill();ctx.beginPath();ctx.arc(790-camera*.05,100,20,.25,Math.PI-.25);ctx.stroke();
for(let i=-1;i<10;i++){let x=i*150-(camera*.22%150);tree(x,250,1.1,'#8e724d');}for(let i=-1;i<10;i++){let x=i*225-(camera*.48%225);tree(x,325,.85,'#70583c');}
ctx.fillStyle='#92724b';ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle='#58402c';ctx.fillRect(0,GROUND+17,W,H-GROUND-17);for(let x=-(camera%80);x<W;x+=80){ctx.strokeStyle='#6b5034';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,GROUND+28);ctx.lineTo(x+25,GROUND+20);ctx.lineTo(x+43,GROUND+29);ctx.stroke();}for(let x=20-(camera%110);x<W;x+=110){ctx.fillStyle='#b9a06b';ctx.beginPath();ctx.ellipse(x,GROUND+4,18,5,0,0,Math.PI*2);ctx.fill();}}
function tree(x,y,s,c){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle=c;ctx.strokeStyle='#49331f';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-20,230);ctx.quadraticCurveTo(-3,100,-18,0);ctx.quadraticCurveTo(0,-40,24,0);ctx.quadraticCurveTo(4,110,24,230);ctx.closePath();ctx.fill();ctx.stroke();for(const [a,b,r] of [[-25,25,48],[20,5,56],[0,-25,52]]){ctx.beginPath();ctx.ellipse(a,b,r,r*.7,.2,0,Math.PI*2);ctx.fill();ctx.stroke();}ctx.strokeStyle='#c9a974';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-4,135);ctx.quadraticCurveTo(-43,108,-54,130);ctx.moveTo(6,104);ctx.quadraticCurveTo(42,72,48,93);ctx.stroke();ctx.restore();}
function terrain(){for(let x=0;x<LEVEL;x+=450){ctx.fillStyle='#a98a59';ctx.beginPath();ctx.ellipse(x+80,GROUND-2,80,10,0,Math.PI,0);ctx.fill();}for(let x=0;x<LEVEL;x+=270){ctx.fillStyle='#46603a';ctx.strokeStyle='#33271a';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(x+30,GROUND-5,16,6,0,0,Math.PI*2);ctx.fill();ctx.stroke();}}
function ink(){ctx.strokeStyle='#382417';ctx.lineWidth=3;ctx.lineJoin='round';ctx.lineCap='round';}
function drawPlayer(){ctx.save();ctx.translate(player.x+player.w/2,player.y);if(player.face<0)ctx.scale(-1,1);let bob=player.ground?Math.sin(player.anim*.22)*2:0;ctx.translate(0,bob);if(player.inv>0&&Math.floor(time/70)%2===0)ctx.globalAlpha=.45;
// legs and shoes
ink();ctx.fillStyle='#342116';ctx.beginPath();ctx.moveTo(-10,47);ctx.quadraticCurveTo(-14,58,-16,59);ctx.quadraticCurveTo(-26,61,-22,65);ctx.lineTo(-2,65);ctx.quadraticCurveTo(2,61,-3,57);ctx.lineTo(1,48);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(8,47);ctx.lineTo(11,58);ctx.quadraticCurveTo(6,61,9,65);ctx.lineTo(27,65);ctx.quadraticCurveTo(31,60,21,58);ctx.lineTo(18,46);ctx.fill();ctx.stroke();
// body
ctx.fillStyle='#f0e2c6';ctx.beginPath();ctx.moveTo(-15,27);ctx.quadraticCurveTo(-15,19,-7,19);ctx.lineTo(11,19);ctx.quadraticCurveTo(16,19,16,27);ctx.lineTo(13,49);ctx.quadraticCurveTo(1,55,-13,49);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#b8432c';ctx.fillRect(-13,37,26,6);ctx.strokeRect(-13,37,26,6);
// head cup
ctx.fillStyle='#fff0d6';ctx.beginPath();ctx.moveTo(-16,4);ctx.quadraticCurveTo(-15,0,-10,0);ctx.lineTo(10,0);ctx.quadraticCurveTo(17,2,15,12);ctx.lineTo(12,26);ctx.quadraticCurveTo(0,31,-13,25);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#bd4730';ctx.fillRect(-17,5,34,5);ctx.strokeRect(-17,5,34,5);ctx.fillStyle='#352216';ctx.beginPath();ctx.ellipse(-5,14,2.4,4,0,0,7);ctx.ellipse(6,14,2.4,4,0,0,7);ctx.fill();ctx.strokeStyle='#482c1a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(1,18,5,.25,2.7);ctx.stroke();
// straw
ctx.strokeStyle='#382417';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-4,1);ctx.lineTo(-3,-8);ctx.lineTo(7,-8);ctx.stroke();ctx.strokeStyle='#b8412e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-3,-5);ctx.lineTo(5,-5);ctx.stroke();
// arm and glove shooting
ctx.strokeStyle='#382417';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(12,29);ctx.quadraticCurveTo(23,29,25,32);ctx.stroke();ctx.fillStyle='#fff5df';ctx.beginPath();ctx.ellipse(27,32,8,7,0,0,7);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(29,31);ctx.lineTo(39,31);ctx.lineTo(38,34);ctx.stroke();ctx.restore();}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);if(e.dir<0&&e.type!=='bee')ctx.scale(-1,1);ink();if(e.type==='mush'){ctx.fillStyle='#e7d8b8';ctx.beginPath();ctx.roundRect(7,21,34,29,8);ctx.fill();ctx.stroke();ctx.fillStyle='#a83f2b';ctx.beginPath();ctx.ellipse(24,22,25,17,0,Math.PI,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#f0deba';for(const [x,y,r] of [[12,16,4],[25,9,5],[37,16,4]]){ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();}ctx.fillStyle='#382417';ctx.beginPath();ctx.arc(18,31,2,0,7);ctx.arc(30,31,2,0,7);ctx.fill();ctx.beginPath();ctx.arc(24,35,5,.2,2.9);ctx.stroke();ctx.fillStyle='#382417';ctx.beginPath();ctx.ellipse(14,49,9,3,0,0,7);ctx.ellipse(34,49,9,3,0,0,7);ctx.fill();}
else if(e.type==='bee'){let wing=Math.sin(time/50)*5;ctx.fillStyle='#f4dfb5';ctx.beginPath();ctx.ellipse(22,5+wing,10,16,-.5,0,7);ctx.ellipse(39,5-wing,10,16,.5,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#e2b849';ctx.beginPath();ctx.ellipse(26,21,22,14,0,0,7);ctx.fill();ctx.stroke();ctx.strokeStyle='#382417';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(23,9);ctx.lineTo(23,33);ctx.moveTo(36,9);ctx.lineTo(36,33);ctx.stroke();ctx.fillStyle='#f4e3bf';ctx.beginPath();ctx.arc(9,18,11,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#382417';ctx.beginPath();ctx.arc(7,16,2,0,7);ctx.fill();ctx.strokeStyle='#382417';ctx.lineWidth=2;ctx.beginPath();ctx.arc(11,21,4,.2,2.5);ctx.stroke();ctx.stroke();ctx.beginPath();ctx.moveTo(2,6);ctx.quadraticCurveTo(-1,-3,5,-4);ctx.stroke();}
else{ctx.fillStyle='#71904d';ctx.beginPath();ctx.ellipse(25,27,24,17,0,0,7);ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(40,12,13,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#f6e8ca';ctx.beginPath();ctx.ellipse(35,2,5,9,0,0,7);ctx.ellipse(47,2,5,9,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#382417';ctx.beginPath();ctx.arc(38,11,2,0,7);ctx.arc(47,11,2,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(41,17);ctx.quadraticCurveTo(46,21,51,17);ctx.stroke();ctx.strokeStyle='#382417';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(10,38);ctx.lineTo(0,47);ctx.lineTo(14,48);ctx.moveTo(34,39);ctx.lineTo(47,47);ctx.lineTo(31,48);ctx.stroke();}ctx.restore();}

function drawBoss(b){ctx.save();ctx.translate(b.x,b.y);ink();const pulse=Math.sin(time/140)*3;ctx.strokeStyle='#46603a';ctx.lineWidth=16;ctx.beginPath();ctx.moveTo(75,90);ctx.quadraticCurveTo(63,145,78,205);ctx.stroke();ctx.fillStyle='#567343';ctx.beginPath();ctx.ellipse(47,161,34,11,-.4,0,7);ctx.ellipse(103,173,35,12,.3,0,7);ctx.fill();ctx.stroke();
// petals
for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.save();ctx.translate(75,67);ctx.rotate(a);ctx.fillStyle=i%2?'#bd4935':'#cf5c40';ctx.beginPath();ctx.ellipse(0,-50-pulse,23,48,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#e49a68';ctx.beginPath();ctx.ellipse(-5,-70-pulse,5,12,-.2,0,7);ctx.fill();ctx.restore();}
ctx.fillStyle='#d5aa45';ctx.beginPath();ctx.arc(75,67,48,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#edcf7c';ctx.beginPath();ctx.arc(61,56,4,0,7);ctx.arc(87,56,4,0,7);ctx.fill();ctx.strokeStyle='#382417';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(48,48);ctx.lineTo(66,55);ctx.moveTo(101,48);ctx.lineTo(83,55);ctx.stroke();ctx.fillStyle='#382417';ctx.beginPath();ctx.ellipse(61,68,4,6,0,0,7);ctx.ellipse(88,68,4,6,0,0,7);ctx.fill();ctx.strokeStyle='#382417';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(55,84);ctx.quadraticCurveTo(75,72,97,84);ctx.stroke();ctx.fillStyle='#fff0d6';ctx.beginPath();ctx.moveTo(65,81);ctx.lineTo(71,81);ctx.lineTo(68,91);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(81,81);ctx.lineTo(87,81);ctx.lineTo(84,91);ctx.closePath();ctx.fill();if(b.flash>0){ctx.globalAlpha=.35;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(75,67,46,0,7);ctx.fill();}ctx.restore();}
function hud(){ctx.save();ctx.fillStyle='#2e2015d9';ctx.strokeStyle='#e3c88e';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(16,14,195,55,8);ctx.fill();ctx.stroke();ctx.fillStyle='#f0dfbd';ctx.font='24px Bangers';ctx.fillText('MUGSY',29,38);for(let i=0;i<3;i++){ctx.fillStyle=i<player.hp?'#b8432f':'#554638';ctx.beginPath();ctx.arc(42+i*28,54,9,0,7);ctx.fill();ctx.strokeStyle='#f1d8a6';ctx.lineWidth=1.5;ctx.stroke();}ctx.fillStyle='#f2dfb6';ctx.font='18px Bangers';ctx.fillText('WOODLAND MILE '+Math.min(3,Math.floor(player.x/1300)+1),230,35);ctx.fillText('✦ '+score,230,59);
if(boss){ctx.fillStyle='#2e2015e8';ctx.beginPath();ctx.roundRect(324,17,312,35,8);ctx.fill();ctx.strokeStyle='#e3c88e';ctx.stroke();ctx.fillStyle='#a33f2b';ctx.fillRect(334,27,292*(boss.hp/boss.max),15);ctx.strokeStyle='#f3dfb2';ctx.strokeRect(334,27,292,15);ctx.fillStyle='#f3e3c3';ctx.font='18px Bangers';ctx.textAlign='center';ctx.fillText('THE WICKED WILDFLOWER',480,16);ctx.textAlign='left';}
if(state==='play'&&player.x<150) {ctx.textAlign='right';ctx.fillStyle='#37251a';ctx.font='19px Bangers';ctx.fillText('ARROWS MOVE  •  X JUMP  •  Z SHOOT  •  C DASH',944,33);ctx.textAlign='left';}ctx.restore();}
function titleScreen(){ctx.fillStyle='#25190fdc';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#e5cb91';ctx.lineWidth=5;ctx.strokeRect(22,20,W-44,H-40);ctx.textAlign='center';ctx.fillStyle='#f2d89e';ctx.font='62px Rye';ctx.fillText("MUGSY'S",480,138);ctx.font='68px Rye';ctx.fillStyle='#c95439';ctx.fillText('WOODLAND RUMBLE',480,209);ctx.font='27px Bangers';ctx.fillStyle='#f2e3c4';ctx.fillText('A MOST UNFORTUNATE FOREST ADVENTURE',480,258);ctx.font='23px Bangers';ctx.fillText('RUN   •   DOUBLE JUMP   •   DASH   •   PARRY THE PINK!',480,308);ctx.font='21px Bangers';ctx.fillText('ARROWS MOVE  |  X / SPACE JUMP  |  Z SHOOT  |  C DASH',480,344);ctx.textAlign='left';}
