const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const W=960,H=540,GROUND=446,LEVEL=4200;canvas.width=W;canvas.height=H;
const startBtn=document.querySelector('#startBtn'),pauseBtn=document.querySelector('#pauseBtn');
const keys=new Set(),held={left:false,right:false,shoot:false,jump:false,dash:false};
let state='title',last=0,time=0,camera=0,shake=0,particles=[],shots=[],enemyShots=[],enemies=[],boss=null,score=0,parryFlash=0;
const player={x:90,y:GROUND-62,w:42,h:62,vx:0,vy:0,face:1,hp:3,ground:false,jumps:0,fire:0,dash:0,dashCD:0,inv:0,anim:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function reset(){player.x=90;player.y=GROUND-62;player.vx=player.vy=0;player.hp=3;player.face=1;player.jumps=0;player.inv=0;player.dashCD=0;camera=0;shots=[];enemyShots=[];particles=[];score=0;boss=null;enemies=[{type:'mush',x:540,y:GROUND-48,hp:2,dir:-1,base:GROUND},{type:'bee',x:980,y:290,hp:2,dir:-1,base:290,phase:0},{type:'frog',x:1430,y:GROUND-46,hp:2,dir:-1,base:GROUND,jump:1},{type:'mush',x:1840,y:GROUND-48,hp:2,dir:-1,base:GROUND},{type:'bee',x:2200,y:270,hp:2,dir:-1,base:270,phase:2},{type:'frog',x:2580,y:GROUND-46,hp:2,dir:-1,base:GROUND,jump:2}];}
reset();
function begin(){if(state==='title'||state==='lose'||state==='win'){reset();state='play';startBtn.hidden=true;pauseBtn.hidden=false;}}
startBtn.addEventListener('click',begin);pauseBtn.addEventListener('click',()=>{if(state==='play')state='pause';else if(state==='pause')state='play';});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','z','x','c'].includes(k))e.preventDefault();keys.add(k);if(k==='enter'&&state!=='play'&&state!=='pause')begin();if(k==='escape'||k==='p'){if(state==='play')state='pause';else if(state==='pause')state='play';}if((k==='x'||k==='arrowup'||k===' ')&&!e.repeat)jump();if(k==='c'&&!e.repeat)dash();});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
for(const b of document.querySelectorAll('[data-input]')){const a=b.dataset.input;const down=e=>{e.preventDefault();held[a]=true;b.classList.add('down');if(a==='jump')jump();if(a==='dash')dash();};const up=e=>{e.preventDefault();held[a]=false;b.classList.remove('down');};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up);}
canvas.addEventListener('pointerdown',()=>{if(state!=='play')begin();else shoot();});
function down(a){return held[a]||keys.has(a==='left'?'arrowleft':a==='right'?'arrowright':a==='shoot'?'z':'');}
function jump(){if(state!=='play')return;if(player.jumps<2){player.vy=-10.8;player.ground=false;player.jumps++;puff(player.x+20,player.y+58,5,'#f1dfbd');}}
function dash(){if(state!=='play'||player.dashCD>0)return;player.dash=12;player.dashCD=48;player.inv=Math.max(player.inv,14);player.vx=player.face*11;player.vy=0;}
function shoot(){if(state!=='play'||player.fire>0)return;player.fire=11;shots.push({x:player.x+player.w/2+player.face*23,y:player.y+29,vx:player.face*9,life:80});puff(player.x+player.w/2+player.face*24,player.y+29,3,'#f7dfa1');}
function puff(x,y,n,color){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*3,vy:(Math.random()-.8)*3,life:20+Math.random()*15,color,r:2+Math.random()*3});}
function rectHit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function hurt(){if(player.inv>0||state!=='play')return;player.hp--;player.inv=90;player.vy=-6;player.vx=-player.face*4;shake=9;puff(player.x+20,player.y+30,12,'#b4432b');if(player.hp<=0){state='lose';startBtn.textContent='TRY AGAIN';startBtn.hidden=false;pauseBtn.hidden=true;}}
function spawnBoss(){if(!boss&&player.x>LEVEL-650)boss={x:LEVEL-390,y:GROUND-210,w:150,h:210,hp:10,max:10,mode:'seed',timer:70,flash:0};}
function update(dt){if(state!=='play')return;time+=dt;const s=dt/16.67;player.anim+=s;player.fire=Math.max(0,player.fire-s);player.dashCD=Math.max(0,player.dashCD-s);player.inv=Math.max(0,player.inv-s);player.dash=Math.max(0,player.dash-s);if(shake>0)shake*=.85;
const dir=(down('right')?1:0)-(down('left')?1:0);if(dir){player.face=dir;if(!player.dash)player.vx=dir*3.25;}else if(!player.dash)player.vx*=.78;if(down('shoot'))shoot();if(player.dash<=0)player.vy+=.48*s;player.x+=player.vx*s;player.y+=player.vy*s;player.x=clamp(player.x,0,LEVEL-40);
if(player.y+player.h>=GROUND){player.y=GROUND-player.h;player.vy=0;if(!player.ground)player.jumps=0;player.ground=true;}else player.ground=false;if(player.y>H+100)hurt();camera=clamp(player.x-330,0,LEVEL-W+160);
for(let i=shots.length-1;i>=0;i--){let b=shots[i];b.x+=b.vx*s;b.life-=s;if(b.life<=0||b.x<camera-30||b.x>camera+W+30)shots.splice(i,1);}
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(e.hp<=0){puff(e.x+20,e.y+20,12,'#9b3429');enemies.splice(i,1);score++;continue;}if(e.baseX===undefined)e.baseX=e.x;if(e.type==='mush'){e.x+=e.dir*.65*s;if(e.x<e.baseX-90||e.x>e.baseX+90)e.dir*=-1;}if(e.type==='bee'){e.phase+=.05*s;e.x+=e.dir*.8*s;e.y=e.base+Math.sin(e.phase)*25;if(e.x<e.baseX-75||e.x>e.baseX+75)e.dir*=-1;}if(e.type==='frog'){e.jump-=s;if(e.jump<=0){e.vy=-8;e.jump=85;}e.vy=(e.vy||0)+.38*s;e.y+=e.vy*s;if(e.y>GROUND-46){e.y=GROUND-46;e.vy=0;}e.x+=e.dir*.6*s;}
const box={x:e.x,y:e.y,w:e.type==='bee'?44:46,h:e.type==='bee'?32:48};for(let j=shots.length-1;j>=0;j--)if(rectHit({x:shots[j].x-5,y:shots[j].y-4,w:10,h:8},box)){e.hp--;shots.splice(j,1);}if(rectHit({x:player.x+5,y:player.y+5,w:player.w-10,h:player.h-5},box)){if(player.dash>0)e.hp--;else hurt();}}
if(player.x>LEVEL-330)spawnBoss();if(boss){const b=boss;b.timer-=s;b.flash=Math.max(0,b.flash-s);if(b.mode==='seed'&&b.timer<=0){for(let i=-1;i<=1;i++)enemyShots.push({x:b.x+40,y:b.y+75,vx:-3.5,vy:i*1.35,pink:i===0,life:160});b.mode='slam';b.timer=95;}else if(b.mode==='slam'&&b.timer<=0){b.mode='rise';b.timer=42;b.y=GROUND-210;shake=10;}else if(b.mode==='rise'&&b.timer<=0){b.mode='bees';b.timer=90;for(let i=0;i<2;i++)enemies.push({type:'bee',x:b.x-50-i*45,y:b.y+50,hp:2,dir:-1,base:b.y+50,baseX:b.x-50-i*45,phase:i});}else if(b.mode==='bees'&&b.timer<=0){b.mode='seed';b.timer=85;}if(b.mode==='slam'){b.y+=8*s;if(b.y+b.h>=GROUND){b.y=GROUND-b.h;shake=12;}}
const bb={x:b.x+10,y:b.y+20,w:b.w-20,h:b.h-20};for(let j=shots.length-1;j>=0;j--)if(rectHit({x:shots[j].x-5,y:shots[j].y-5,w:10,h:10},bb)){b.hp--;b.flash=9;shots.splice(j,1);puff(b.x+35,b.y+80,3,'#f7da8d');}if(rectHit({x:player.x+4,y:player.y+5,w:player.w-8,h:player.h-6},bb)){if(player.dash>0)b.hp--;else hurt();}if(b.hp<=0){boss=null;state='win';startBtn.textContent='PLAY AGAIN';startBtn.hidden=false;pauseBtn.hidden=true;puff(LEVEL-330,220,70,'#e9c66e');}}
for(let i=enemyShots.length-1;i>=0;i--){const b=enemyShots[i];b.x+=b.vx*s;b.y+=b.vy*s;b.life-=s;if(b.pink&&player.dash>0&&Math.abs(b.x-(player.x+20))<34&&Math.abs(b.y-(player.y+30))<38){enemyShots.splice(i,1);player.hp=Math.min(3,player.hp+1);player.dashCD=0;parryFlash=22;puff(b.x,b.y,10,'#ed78ad');continue;}if(rectHit({x:b.x-9,y:b.y-9,w:18,h:18},{x:player.x,y:player.y,w:player.w,h:player.h})){enemyShots.splice(i,1);hurt();continue;}if(b.life<=0||b.x<camera-100)enemyShots.splice(i,1);}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*s;p.y+=p.vy*s;p.vy+=.1*s;p.life-=s;if(p.life<=0)particles.splice(i,1);}parryFlash=Math.max(0,parryFlash-s);}
// DRAWING

