// DRAWING
function draw(){ctx.save();ctx.translate(shake?((Math.random()-.5)*shake):0,0);background();ctx.save();ctx.translate(-camera,0);terrain();for(const e of enemies)drawEnemy(e);if(boss)drawBoss(boss);for(const b of shots){ctx.fillStyle='#f8d783';ctx.beginPath();ctx.ellipse(b.x,b.y,8,5,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#4b2d17';ctx.lineWidth=2;ctx.stroke();}for(const b of enemyShots){ctx.fillStyle=b.pink?'#ef79a5':'#b8432d';ctx.beginPath();ctx.ellipse(b.x,b.y,10,7,Math.sin(time/120),0,Math.PI*2);ctx.fill();ctx.strokeStyle='#482717';ctx.lineWidth=2;ctx.stroke();}drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/24,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.restore();hud();if(parryFlash>0){ctx.strokeStyle='#ee7ba8';ctx.lineWidth=8;ctx.globalAlpha=parryFlash/22;ctx.beginPath();ctx.arc(480,270,120,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}if(state==='title')titleScreen();if(state==='pause')overlay('PAUSED','Press P to resume');if(state==='lose')overlay('CURSES!','Your three chances are gone');if(state==='win')overlay('YOU DID IT!','THE WOODLAND IS FREE');film();ctx.restore();}
function background(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#d9bd87');g.addColorStop(.68,'#b58e5c');g.addColorStop(1,'#77543a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='#f4d786';ctx.beginPath();ctx.arc(790-camera*.05,100,53,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#49321e';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#4b321f';ctx.beginPath();ctx.arc(774-camera*.05,93,4,0,7);ctx.arc(806-camera*.05,93,4,0,7);ctx.fill();ctx.beginPath();ctx.arc(790-camera*.05,100,20,.25,Math.PI-.25);ctx.stroke();for(let i=-1;i<10;i++)tree(i*150-(camera*.22%150),250,1.1,'#8e724d');for(let i=-1;i<10;i++)tree(i*225-(camera*.48%225),325,.85,'#70583c');ctx.fillStyle='#92724b';ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle='#58402c';ctx.fillRect(0,GROUND+17,W,H-GROUND-17);for(let x=-(camera%80);x<W;x+=80){ctx.strokeStyle='#6b5034';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,GROUND+28);ctx.lineTo(x+25,GROUND+20);ctx.lineTo(x+43,GROUND+29);ctx.stroke();}for(let x=20-(camera%110);x<W;x+=110){ctx.fillStyle='#b9a06b';ctx.beginPath();ctx.ellipse(x,GROUND+4,18,5,0,0,Math.PI*2);ctx.fill();}}
function tree(x,y,s,c){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle=c;ctx.strokeStyle='#49331f';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-20,230);ctx.quadraticCurveTo(-3,100,-18,0);ctx.quadraticCurveTo(0,-40,24,0);ctx.quadraticCurveTo(4,110,24,230);ctx.closePath();ctx.fill();ctx.stroke();for(const [a,b,r] of [[-25,25,48],[20,5,56],[0,-25,52]]){ctx.beginPath();ctx.ellipse(a,b,r,r*.7,.2,0,Math.PI*2);ctx.fill();ctx.stroke();}ctx.strokeStyle='#c9a974';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-4,135);ctx.quadraticCurveTo(-43,108,-54,130);ctx.moveTo(6,104);ctx.quadraticCurveTo(42,72,48,93);ctx.stroke();ctx.restore();}
