function drawBoss(b){ctx.save();ctx.translate(b.x,b.y);ink();const pulse=Math.sin(time/140)*3;ctx.strokeStyle='#46603a';ctx.lineWidth=16;ctx.beginPath();ctx.moveTo(75,90);ctx.quadraticCurveTo(63,145,78,205);ctx.stroke();ctx.fillStyle='#567343';ctx.beginPath();ctx.ellipse(47,161,34,11,-.4,0,7);ctx.ellipse(103,173,35,12,.3,0,7);ctx.fill();ctx.stroke();for(let i=0;i<8;i++){let a=i*Math.PI/4;ctx.save();ctx.translate(75,67);ctx.rotate(a);ctx.fillStyle=i%2?'#bd4935':'#cf5c40';ctx.beginPath();ctx.ellipse(0,-50-pulse,23,48,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#e49a68';ctx.beginPath();ctx.ellipse(-5,-70-pulse,5,12,-.2,0,7);ctx.fill();ctx.restore();}ctx.fillStyle='#d5aa45';ctx.beginPath();ctx.arc(75,67,48,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#edcf7c';ctx.beginPath();ctx.arc(61,56,4,0,7);ctx.arc(87,56,4,0,7);ctx.fill();ctx.strokeStyle='#382417';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(48,48);ctx.lineTo(66,55);ctx.moveTo(101,48);ctx.lineTo(83,55);ctx.stroke();ctx.fillStyle='#382417';ctx.beginPath();ctx.ellipse(61,68,4,6,0,0,7);ctx.ellipse(88,68,4,6,0,0,7);ctx.fill();ctx.strokeStyle='#382417';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(55,84);ctx.quadraticCurveTo(75,72,97,84);ctx.stroke();ctx.fillStyle='#fff0d6';ctx.beginPath();ctx.moveTo(65,81);ctx.lineTo(71,81);ctx.lineTo(68,91);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(81,81);ctx.lineTo(87,81);ctx.lineTo(84,91);ctx.closePath();ctx.fill();if(b.flash>0){ctx.globalAlpha=.35;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(75,67,46,0,7);ctx.fill();}ctx.restore();}
function hud(){ctx.save();ctx.fillStyle='#2e2015d9';ctx.strokeStyle='#e3c88e';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(16,14,195,55,8);ctx.fill();ctx.stroke();ctx.fillStyle='#f0dfbd';ctx.font='24px Bangers';ctx.fillText('MUGSY',29,38);for(let i=0;i<3;i++){ctx.fillStyle=i<player.hp?'#b8432f':'#554638';ctx.beginPath();ctx.arc(42+i*28,54,9,0,7);ctx.fill();ctx.strokeStyle='#f1d8a6';ctx.lineWidth=1.5;ctx.stroke();}ctx.fillStyle='#f2dfb6';ctx.font='18px Bangers';ctx.fillText('WOODLAND MILE '+Math.min(3,Math.floor(player.x/1300)+1),230,35);ctx.fillText('✦ '+score,230,59);if(boss){ctx.fillStyle='#2e2015e8';ctx.beginPath();ctx.roundRect(324,17,312,35,8);ctx.fill();ctx.strokeStyle='#e3c88e';ctx.stroke();ctx.fillStyle='#a33f2b';ctx.fillRect(334,27,292*(boss.hp/boss.max),15);ctx.strokeStyle='#f3dfb2';ctx.strokeRect(334,27,292,15);ctx.fillStyle='#f3e3c3';ctx.font='18px Bangers';ctx.textAlign='center';ctx.fillText('THE WICKED WILDFLOWER',480,16);ctx.textAlign='left';}if(state==='play'&&player.x<150){ctx.textAlign='right';ctx.fillStyle='#37251a';ctx.font='19px Bangers';ctx.fillText('ARROWS MOVE  •  X JUMP  •  Z SHOOT  •  C DASH',944,33);ctx.textAlign='left';}ctx.restore();}
function titleScreen(){ctx.fillStyle='#25190fdc';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#e5cb91';ctx.lineWidth=5;ctx.strokeRect(22,20,W-44,H-40);ctx.textAlign='center';ctx.fillStyle='#f2d89e';ctx.font='62px Rye';ctx.fillText("MUGSY'S",480,138);ctx.font='68px Rye';ctx.fillStyle='#c95439';ctx.fillText('WOODLAND RUMBLE',480,209);ctx.font='27px Bangers';ctx.fillStyle='#f2e3c4';ctx.fillText('A MOST UNFORTUNATE FOREST ADVENTURE',480,258);ctx.font='23px Bangers';ctx.fillText('RUN   •   DOUBLE JUMP   •   DASH   •   PARRY THE PINK!',480,308);ctx.font='21px Bangers';ctx.fillText('ARROWS MOVE  |  X / SPACE JUMP  |  Z SHOOT  |  C DASH',480,344);ctx.textAlign='left';}
function overlay(title,subtitle){ctx.fillStyle='#24180fe5';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#e3c88e';ctx.lineWidth=5;ctx.strokeRect(25,24,W-50,H-48);ctx.textAlign='center';ctx.fillStyle=title==='YOU DID IT!'?'#f0d17a':'#f1dfbd';ctx.font=title==='YOU DID IT!'?'80px Rye':'70px Rye';ctx.fillText(title,480,245);ctx.font='30px Bangers';ctx.fillStyle='#f0dfbd';ctx.fillText(subtitle,480,295);if(state==='pause')ctx.fillText('Press P or ESC to return',480,345);ctx.textAlign='left';}
